  AwakerStory_96418_Content = {
    Text = "Основатель Некрополиса, вечный король мертвецов. \n Его пиршество стоит самого глубокого ожидания — великолепный ресторан, изящные танцы и те утонченные блюда, которые он приготовил из останков, обязательно оставят у вас незабываемые впечатления."
